module TypeScript {
    export class ScopeChain {
        public thisType: Type;
        public classType: Type;
        public fnc: FuncDecl;
        public moduleDecl: ModuleDeclaration;

        constructor (public container: Symbol, public previous: ScopeChain,
                     public scope: SymbolScope) { }
